source("lib.R")
p <- function(label, x) cat(sprintf("%-28s %s\n", label, substr(paste(capture.output(print(x)), collapse=" / "), 1, 500)))
s <- suppressWarnings(cache(tempfile("c-"), cull_limit = 2^31, size_limit = 2000))
p("cull_limit stored", s$cull_limit)
p("set w/ NA cull", tr({for (i in 1:30) cache_set(s, paste0("k", i), as.raw(1:200)); cache_count(s)}))
p("expire w/ NA cull", tr({cache_set(s, "e", 1, expire = -1); cache_expire(s); cache_count(s)}))
p("cull w/ NA cull", tr({cache_cull(s); cache_count(s)}))
cache_close(s)
s <- cache(tempfile("c-"))
p("incr i64 class", tr(class(cache_incr(s, "c", by = bit64::as.integer64(3)))))
p("incr i64 again", tr({r <- cache_incr(s, "c", by = bit64::as.integer64(3)); list(class(r), as.character(r))}))
p("incr i64 big", tr(cache_incr(s, "c2", by = bit64::as.integer64("9007199254740993"))))
p("incr i64 default", tr({r <- cache_incr(s, "c3", default = bit64::as.integer64(7)); list(class(r), r, cache_get(s, "c3"))}))
p("get after i64", tr(cache_get(s, "c")))
p("expire n", tr({for (i in 1:5) cache_set(s, paste0("x", i), 1, expire = -1); cache_expire(s, n = 2); cache_count(s)}))
p("expire n bad", tr(cache_expire(s, n = -1))); p("expire n frac", tr(cache_expire(s, n = 1.5))); p("expire n 0", tr({cache_expire(s, n = 0); cache_count(s)}))
p("evict none", tr(cache_evict(s))); p("evict both", tr(cache_evict(s, tag = "a", prefix = "b"))); p("evict tag NA", tr(cache_evict(s, tag = NA_character_))); p("evict tag ''", tr(cache_evict(s, tag = ""))); p("evict tag vec", tr(cache_evict(s, tag = c("a", "b"))))
p("evict prefix '' clears", tr({cache_evict(s, prefix = ""); cache_count(s)}))
p("evict prefix structured", tr({cache_set(s, list(a = 1), 1); cache_set(s, "{a", 2); cache_evict(s, prefix = "{a"); cache_keys(s)}))
p("evict tag prefix-of-tag", tr({cache_set(s, "t1", 1, tags = "ab"); cache_set(s, "t2", 1, tags = "a"); cache_set(s, "t3", 1, tags = c("a\001b")); cache_evict(s, tag = "a"); cache_keys(s)}))
p("tag with NUL-sep trick", tr({cache_set(s, "t4", 1, tags = "x"); cache_entries(s, tag = "a\001b")$key}))
p("transact", tr(cache_transact(s, {cache_set(s, "tx1", 1); cache_incr(s, "txc"); cache_get(s, "tx1")})))
p("transact rollback", tr({tr(cache_transact(s, {cache_set(s, "tx2", 1); stop("x")})); cache_has(s, "tx2")}))
p("transact missing", tr(cache_transact(s)))
p("path inline", tr(cache_path(s, "tx1"))); p("path missing", tr(cache_path(s, "nokey")))
p("codec name bad", c(tr(class(codec(1, identity, identity))), tr(class(codec("", identity, identity))), tr(class(codec("rds", function(v, p) NULL, function(p, m) NULL))), tr(class(codec("A b", function(v, p) NULL, function(p, m) NULL))), tr(class(codec("x", 1, 2))), tr(class(codec("x", function(v, p) NULL, function(p, m) NULL, version = 1.5))), tr(class(codec("x", function(v, p) NULL, function(p, m) NULL, version = 2^31))), tr(class(codec("x", function(v, p) NULL, function(p, m) NULL, ext = c("a", "b")))), tr(class(codec("x", function(v, p) NULL, function(p, m) NULL, ext = "a/b")))))
p("codec_rds compress", tr(codec_rds(NA))); p("print codec", tr(capture.output(print(codec_rds()))))
# not_found condition fields
e <- tryCatch(cache_get(s, list(a = 2)), error = function(e) e); p("nf fields", list(class(e)[1:2], e$key, conditionMessage(e)))
e <- tryCatch(cache_mget(s, c("m1", "m2", "tx1")), error = function(e) e); p("mget nf fields", list(e$key, conditionMessage(e)))
p("display long key", tr(conditionMessage(tryCatch(cache_get(s, strrep("é", 300)), error = function(e) e))))
p("display nl key", tr(conditionMessage(tryCatch(cache_get(s, "a\nb\"c"), error = function(e) e))))
old <- options(warn = 2, OutDec = ",", scipen = -5, digits = 3)
p("warn2 basic ops", tr({cache_set(s, 0.1, 1.5); cache_set(s, 123456.789, 2, expire = 1e5, tags = "a"); cache_incr(s, "w", by = 1e5); cache_mset(s, list(a = 1)); cache_keys(s, n = 1e5); cache_entries(s); cache_stats(s); cache_key_chr(list(1e5, 1e-5, 1e15, 0.1, 100000L, as.Date("2026-01-01"), Sys.time())); cache_key_chr(1e5)}))
p("warn2 key 1e5", cache_keys(s, prefix = "f:")); p("hostile get", cache_get(s, 123456.789))
options(old)
p("has double key", cache_has(s, list(0.1, 123456.789)))
